#!/usr/bin/env python3
"""Generate PTN's crawlable HTML. No dependencies or cloud services required."""
from pathlib import Path
from html import escape
import csv
import hashlib
import json
import xml.etree.ElementTree as ET

ROOT = Path(__file__).resolve().parents[1]
SITE = json.loads((ROOT / 'content/site.json').read_text())
SERVICES = json.loads((ROOT / 'content/services.json').read_text())
BY_SLUG = {s['slug']: s for s in SERVICES}
SEO_PLAN = {p['slug']: p for p in json.loads((ROOT / 'content/seo-plan.json').read_text())}
URL = SITE['url']
FAVICON_VERSION = hashlib.sha256((ROOT / 'favicon.svg').read_bytes()).hexdigest()[:10]
ASSET_VERSIONS = {name: hashlib.sha256((ROOT / 'assets' / name).read_bytes()).hexdigest()[:10] for name in ('site.css', 'site.js')}
ROUTES = []
T = {
'es': {'home':'Inicio','services':'Servicios','clients':'Clientes','brands':'Distribuidores','about':'Nosotros','contact':'Contacto','quote':'Solicitar cotización','whatsapp':'Hablar por WhatsApp','all':'Ver todos los servicios','related':'Servicios relacionados','questions':'Preguntas frecuentes','scope':'Qué considerar en este servicio','decide':'Antes de elegir','prepare':'Qué enviar para cotizar','process':'Cómo plantear tu proyecto','nationwide':'Envíos en México','location':'Monterrey, Nuevo León','skip':'Saltar al contenido','menu':'Menú','footer':'Uniformes, personalización y materia prima textil para empresas. Atención desde Monterrey y cobertura nacional.','next':'Cuéntanos qué necesita tu equipo.','nextSub':'Comparte tu proyecto y revisemos prendas, materiales, cantidades y entrega.','caption':'Uniformes y soluciones textiles para empresas.','serviceLabel':'Servicio','other':'Necesito orientación','formTitle':'Prepara tu solicitud de cotización','formIntro':'Reúne los datos del proyecto para revisarlos con un asesor de PTN.','formNote':'Al continuar se abre WhatsApp con un borrador para que lo revises y lo envíes. Este sitio no envía el mensaje ni almacena la solicitud. También puedes llamar o escribir por correo.','formButton':'Preparar solicitud en WhatsApp','name':'Nombre','company':'Empresa','email':'Correo electrónico','phone':'Teléfono (opcional)','quantity':'Cantidad aproximada (opcional)','city':'Ciudad de entrega','message':'Detalles del proyecto (opcional)','hours':'Lunes a viernes, 9:00–18:00','address':'Oficinas y planta','back':'Volver al inicio','supply':'Suministro y operación','uniforms':'Uniformes','customization':'Personalización','compare':'Compara las técnicas de personalización'},
'en': {'home':'Home','services':'Services','clients':'Clients','brands':'Brands','about':'About','contact':'Contact','quote':'Request a quote','whatsapp':'Talk on WhatsApp','all':'View all services','related':'Related services','questions':'Frequently asked questions','scope':'What to consider for this service','decide':'Before you choose','prepare':'What to send for a quote','process':'Plan your project','nationwide':'Shipping in Mexico','location':'Monterrey, Nuevo León','skip':'Skip to content','menu':'Menu','footer':'Uniforms, customization and textile materials for businesses. Based in Monterrey with nationwide coverage in Mexico.','next':'Tell us what your team needs.','nextSub':'Share your project to discuss garments, materials, quantities and delivery.','caption':'Uniforms and textile solutions for businesses.','serviceLabel':'Service','other':'I need advice','formTitle':'Prepare your quote request','formIntro':'Gather the project details to review with a PTN advisor.','formNote':'Continuing opens a WhatsApp draft for you to review and send. This site does not send the message or store the request. You can also call or email PTN.','formButton':'Prepare request in WhatsApp','name':'Name','company':'Company','email':'Email','phone':'Phone (optional)','quantity':'Approximate quantity (optional)','city':'Delivery city','message':'Project details (optional)','hours':'Monday–Friday, 9:00–18:00','address':'Offices and plant','back':'Back to home','supply':'Supply and operations','uniforms':'Uniforms','customization':'Customization','compare':'Compare customization techniques'}
}
PATHS = {'es':{'home':'/','services':'/servicios/','clients':'/clientes/','brands':'/distribuidores/','about':'/nosotros/','contact':'/contacto/'},'en':{'home':'/en/','services':'/en/services/','clients':'/en/clients/','brands':'/en/brands/','about':'/en/about/','contact':'/en/contact/'}}

def e(value): return escape(str(value), quote=True)
def route(key,lang): return PATHS[lang][key]
def service_route(s,lang): return ('/servicios/'+s['slug']+'/' if lang=='es' else '/en/services/'+s['enSlug']+'/')
def media(name): return SITE.get('heroImage', '/assets/media/soluciones-textiles.webp') if name=='soluciones-textiles' else '/assets/media/'+name+'.webp'
def img(name,alt,hero=False,cls='feature-image'):
    height = 800 if name=='soluciones-textiles' else (831 if name=='bordado' else 675)
    return f'<img class="{cls}" src="{media(name)}" alt="{e(alt)}" width="1200" height="{height}" '+('fetchpriority="high" decoding="async"' if hero else 'loading="lazy" decoding="async"')+'>'
def quote_link(lang,slug=''): return route('contact',lang)+('?servicio='+slug if slug else '')
def actions(lang,slug='',light=False):
    t=T[lang]; d=BY_SLUG.get(slug); name=d[lang]['name'] if d else ('mi proyecto textil' if lang=='es' else 'my textile project')
    from urllib.parse import quote
    message = ('Hola PTN, me gustaría cotizar: ' if lang=='es' else 'Hello PTN, I would like a quote for: ')+name
    wa='https://wa.me/'+SITE['whatsapp']+'?text='+quote(message)
    return f'<div class="actions"><a class="button {"light" if light else ""}" data-track="quote_click" data-service="{e(slug)}" href="{quote_link(lang,slug)}">{t["quote"]} <span aria-hidden="true">↗</span></a><a class="button outline" data-track="whatsapp_click" href="{e(wa)}" target="_blank" rel="noopener noreferrer">{t["whatsapp"]}</a></div>'
def nav(lang,key,path,alternates):
    t=T[lang]
    links=''.join(f'<a href="{route(k,lang)}"'+(' aria-current="page"' if key==k else '')+f'>{t[k]}</a>' for k in ['home','services','clients','brands','about','contact'])
    languages=''.join(f'<a href="{alternates[l]}" hreflang="{l}" lang="{l}"'+(' aria-current="page"' if lang==l else '')+f'>{l.upper()}</a>' for l in ['es','en'])
    return f'''<a class="skip" href="#contenido">{t['skip']}</a><div class="topbar"><div class="wrap"><div class="contact-links"><a data-track="phone_click" href="tel:{SITE['phoneRaw']}">{SITE['phone']}</a><a data-track="email_click" href="mailto:{SITE['email']}">{SITE['email']}</a></div><span class="location">{t['location']} — México</span></div></div>
<header class="site-header"><div class="wrap header-row"><a href="{route('home',lang)}" aria-label="PTN — {t['home']}"><img class="logo" src="{SITE['logo']}" alt="PTN — Parches y Textiles del Norte" width="180" height="100"></a><nav id="site-nav" class="site-nav" aria-label="{t['menu']}">{links}</nav><button class="menu-toggle" type="button" aria-label="{'Abrir menú' if lang=='es' else 'Open menu'}" aria-expanded="false" aria-controls="site-nav"><svg class="menu-open" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" aria-hidden="true" focusable="false"><path d="M4 6h16M4 12h16M4 18h16"/></svg><svg class="menu-close" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" aria-hidden="true" focusable="false"><path d="m6 6 12 12M6 18 18 6"/></svg></button><div class="header-actions"><nav class="language" aria-label="{'Idioma' if lang=='es' else 'Language'}">{languages}</nav><a class="button small" data-track="quote_click" href="{quote_link(lang)}">{t['quote']}</a></div></div></header>'''
def footer(lang):
    t=T[lang]
    lists=[]
    for group,label in [('uniformes','uniforms'),('personalizacion','customization')]:
        links=''.join(f'<li><a href="{service_route(s,lang)}">{e(s[lang]["name"])}</a></li>' for s in SERVICES if s['group']==group)
        lists.append(f'<div><h3>{t[label]}</h3><ul>{links}</ul></div>')
    supply=''.join(f'<li><a href="{service_route(s,lang)}">{e(s[lang]["name"])}</a></li>' for s in SERVICES if s['group']=='suministro')
    return f'''<footer class="site-footer"><div class="wrap"><div class="footer-grid"><div><a href="{route('home',lang)}"><img class="logo" src="{SITE['logo']}" alt="PTN" width="180" height="100" loading="lazy"></a><p>{t['footer']}</p><a class="text-link" href="{route('services',lang)}">{t['all']} ↗</a></div>{''.join(lists)}<div><h3>{t['supply']}</h3><ul>{supply}</ul></div></div><div class="footer-bottom"><span>© 2026 {SITE['legalName']}</span><span>{SITE['street']}, {SITE['postalCode']} Monterrey, N.L. · <a href="tel:{SITE['phoneRaw']}" data-track="phone_click">{SITE['phone']}</a> · <a data-track="email_click" href="mailto:{SITE['email']}">{SITE['email']}</a> · <a data-track="whatsapp_click" href="https://wa.me/{SITE['whatsapp']}" target="_blank" rel="noopener noreferrer">WhatsApp</a></span></div></div></footer>'''
def organization():
    return {'@type':'Organization','@id':URL+'/#organization','name':'PTN — Parches y Textiles del Norte','legalName':SITE['legalName'],'url':URL+'/','logo':{'@type':'ImageObject','url':URL+SITE['logo']},'email':SITE['email'],'telephone':SITE['phoneRaw'],'address':{'@type':'PostalAddress','streetAddress':SITE['street'],'addressLocality':SITE['city'],'addressRegion':SITE['region'],'postalCode':SITE['postalCode'],'addressCountry':'MX'},'areaServed':{'@type':'Country','name':'Mexico'}}
def layout(path,lang,title,description,body,key='services',alternates=None,photo='soluciones-textiles',slug='',crumbs=None,noindex=False):
    alternates=alternates or {'es':route(key,'es'),'en':route(key,'en')}
    graph=[organization(),{'@type':'WebSite','@id':URL+'/#website','url':URL+'/','name':'PTN Textiles','publisher':{'@id':URL+'/#organization'}}, {'@type':'WebPage','@id':URL+path+'#webpage','url':URL+path,'name':title,'description':description,'inLanguage':'es-MX' if lang=='es' else 'en','isPartOf':{'@id':URL+'/#website'},'about':{'@id':URL+'/#organization'},'primaryImageOfPage':{'@type':'ImageObject','url':URL+media(photo)}}]
    if slug: graph.append({'@type':'Service','@id':URL+path+'#service','name':BY_SLUG[slug][lang]['name'],'description':description,'url':URL+path,'provider':{'@id':URL+'/#organization'},'areaServed':{'@type':'Country','name':'Mexico'},'serviceType':BY_SLUG[slug][lang]['name']})
    if crumbs: graph.append({'@type':'BreadcrumbList','itemListElement':[{'@type':'ListItem','position':i+1,'name':n,'item':URL+u} for i,(n,u) in enumerate(crumbs)]})
    schema=json.dumps({'@context':'https://schema.org','@graph':graph},ensure_ascii=False).replace('<','\\u003c')
    hreflang=''.join(f'<link rel="alternate" hreflang="{("es-MX" if l=="es" else "en")}" href="{URL+u}">' for l,u in alternates.items())+f'<link rel="alternate" hreflang="x-default" href="{URL+alternates["es"]}">'
    return f'''<!doctype html>
<html lang="{'es-MX' if lang=='es' else 'en'}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{e(title)}</title><meta name="description" content="{e(description)}"><meta name="robots" content="{'noindex,follow' if noindex else 'index,follow,max-image-preview:large'}"><link rel="canonical" href="{URL+path}">{hreflang}<meta property="og:type" content="website"><meta property="og:site_name" content="PTN Textiles"><meta property="og:title" content="{e(title)}"><meta property="og:description" content="{e(description)}"><meta property="og:url" content="{URL+path}"><meta property="og:locale" content="{'es_MX' if lang=='es' else 'en_US'}"><meta property="og:image" content="{URL+media(photo)}"><meta property="og:image:alt" content="{e(BY_SLUG[slug][lang]['name'] if slug else T[lang]['caption'])}"><meta name="twitter:card" content="summary_large_image"><meta name="twitter:title" content="{e(title)}"><meta name="twitter:description" content="{e(description)}"><meta name="twitter:image" content="{URL+media(photo)}"><meta name="theme-color" content="#2e2a80"><link rel="icon" href="/favicon.ico?v={FAVICON_VERSION}" type="image/x-icon" sizes="16x16 32x32 48x48 64x64 256x256"><link rel="icon" href="/favicon.svg?v={FAVICON_VERSION}" type="image/svg+xml" sizes="any"><link rel="preload" as="font" href="/assets/bundle/35ab5943-2eb3-4b61-bfe1-b9d896fac3ee.woff2" type="font/woff2" crossorigin><link rel="stylesheet" href="/assets/site.css?v={ASSET_VERSIONS['site.css']}"><script defer src="/assets/site.js?v={ASSET_VERSIONS['site.js']}"></script><script type="application/ld+json">{schema}</script></head><body data-service="{e(slug)}">{nav(lang,key,path,alternates)}<main id="contenido">{body}</main>{footer(lang)}</body></html>'''
def write(path,html,index=True,alternates=None):
    target=ROOT/(path.strip('/')+'/index.html' if path!='/' else 'index.html')
    target.parent.mkdir(parents=True,exist_ok=True); target.write_text(html)
    if index: ROUTES.append({'path':path,'alternates':alternates})
def breadcrumbs(items): return '<nav class="wrap breadcrumbs" aria-label="Breadcrumb">'+'<span aria-hidden="true">/</span>'.join(f'<a href="{u}">{e(n)}</a>' if i<len(items)-1 else f'<span aria-current="page">{e(n)}</span>' for i,(n,u) in enumerate(items))+'</nav>'
def cards(services,lang):
    return '<div class="service-grid">'+''.join(f'<a class="service-card" href="{service_route(s,lang)}"><span class="number">{i+1:02d}</span><h3>{e(s[lang]["name"])}</h3><p>{e(s[lang]["description"])}</p><span class="arrow" aria-hidden="true">↗</span></a>' for i,s in enumerate(services))+'</div>'
def faq(items,lang):
    return f'<section class="section"><div class="wrap narrow"><span class="eyebrow">{T[lang]["questions"]}</span><h2>{"Respuestas para preparar tu pedido" if lang=="es" else "Answers to help plan your order"}</h2><div class="faq">'+''.join(f'<details><summary>{e(q)}</summary><p>{e(a)}</p></details>' for q,a in items)+'</div></div></section>'
def band(lang,slug=''):
    return f'<section class="band dark"><div class="wrap"><div><h2>{T[lang]["next"]}</h2><p style="margin:15px 0 0">{T[lang]["nextSub"]}</p></div><a class="button light" data-track="quote_click" data-service="{slug}" href="{quote_link(lang,slug)}">{T[lang]["quote"]} ↗</a></div></section>'
def logo_grid(items,brands=False):
    entries=[]
    for row in items:
        name,source=row[:2]; url=row[2] if len(row)>2 else ''
        content=f'<img src="/assets/bundle/{source}" alt="{e(name)}" width="150" height="70" loading="lazy">'
        tag=f'<a class="logo-tile" href="{e(url)}" target="_blank" rel="noopener noreferrer" aria-label="{e(name)}">{content}</a>' if url else f'<div class="logo-tile {"brand-dark" if name=="Blue & White" else ""}">{content}</div>'
        entries.append(tag)
    return '<div class="logo-grid">'+''.join(entries)+'</div>'
def service_page(s,lang):
    t=T[lang]; c=s[lang]; path=service_route(s,lang); alts={l:service_route(s,l) for l in T}; slug=s['slug']
    crumbs=[(t['home'],route('home',lang)),(t['services'],route('services',lang)),(c['name'],path)]
    details=''.join(f'<article class="detail-item"><h3>{e(h)}</h3><p>{e(p)}</p></article>' for h,p in c['details'])
    steps=[('Comparte el alcance','Indica prendas o materiales, cantidades, diseño y destino para revisar la necesidad.'),('Revisa la propuesta','Confirma alternativas, disponibilidad, condiciones y calendario aplicables al proyecto.'),('Acuerda la ejecución','Define las aprobaciones y condiciones antes de autorizar producción o suministro.')] if lang=='es' else [('Share the scope','Describe garments or materials, quantities, artwork and destination.'),('Review the proposal','Confirm alternatives, availability, terms and the applicable schedule.'),('Agree execution','Define approvals and terms before authorizing production or supply.')]
    step_html=''.join(f'<li><span class="num">{i+1:02d}</span><div><strong>{h}</strong><p>{p}</p></div></li>' for i,(h,p) in enumerate(steps))
    body=breadcrumbs(crumbs)+f'''<section class="service-hero"><div class="wrap hero-grid"><div><span class="eyebrow">PTN / {t['location']} / B2B</span><h1>{e(c['title'])}</h1><p class="intro">{e(c['answer'])}</p>{actions(lang,slug)}<div class="tags"><span>{t['nationwide']}</span><span>{'Atención a empresas' if lang=='es' else 'Business projects'}</span></div></div><figure class="hero-figure">{img(s['image'],c['name'],True,'hero-photo')}<figcaption class="photo-note" style="color:var(--muted)">{t['caption']}</figcaption></figure></div></section><section class="section white"><div class="wrap"><span class="eyebrow">{t['scope']}</span><h2>{'Un proyecto definido desde la prenda hasta la entrega' if s['group']=='uniformes' and lang=='es' else ('Del diseño al acabado de la prenda' if s['group']=='personalizacion' and lang=='es' else ('Alcance y decisiones de compra' if lang=='es' else 'Define the scope and purchasing decisions'))}</h2><div class="detail-grid">{details}</div><aside class="decision"><h3>{t['decide']}</h3><p>{e(c['decision'])}</p></aside></div></section><section class="section"><div class="wrap two-col"><div><span class="eyebrow">{t['prepare']}</span><h2>{'Una cotización empieza con información clara' if lang=='es' else 'A useful quote starts with clear information'}</h2><ul class="checklist">{''.join('<li>'+e(item)+'</li>' for item in c['checklist'])}</ul>{actions(lang,slug)}</div><div><span class="eyebrow">{t['process']}</span><ol class="steps">{step_html}</ol></div></div></section>'''
    if slug=='personalizacion-textil':
        rows=[('Bordado','Textura con hilo','Letras, tamaño y soporte textil'),('Serigrafía','Diseño repetido en prendas','Colores, posiciones y tiraje'),('DTF','Transferencia de arte a color','Archivo, superficie y aplicación'),('Sublimación','Personalización en base compatible','Composición y color de la prenda')] if lang=='es' else [('Embroidery','Thread texture','Letter size, dimensions and fabric'),('Screen printing','Repeated garment designs','Colors, placements and run size'),('DTF','Transferred color artwork','File, surface and application'),('Sublimation','Compatible textile base','Composition and garment color')]
        body+=f'<section class="section white"><div class="wrap"><h2>{t["compare"]}</h2><div class="table-wrap"><table><thead><tr>'+''.join('<th scope="col">'+h+'</th>' for h in (['Técnica','Qué aporta','Qué revisar'] if lang=='es' else ['Technique','What it provides','What to review']))+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+e(v)+'</td>' for v in row)+'</tr>' for row in rows)+'</tbody></table></div></div></section>'
    body+=faq(c['faqs'],lang)+band(lang,slug)+f'<section class="section"><div class="wrap"><div class="section-head"><h2>{t["related"]}</h2><a class="text-link" href="{route("services",lang)}">{t["all"]} ↗</a></div>{cards([BY_SLUG[r] for r in s["related"]],lang)}</div></section>'
    write(path,layout(path,lang,c['name']+' en Monterrey | PTN' if lang=='es' else c['name']+' in Monterrey | PTN',c['description'],body,alternates=alts,photo=s['image'],slug=slug,crumbs=crumbs),alternates=alts)

def home(lang):
    t=T[lang]; path=route('home',lang); alts={l:route('home',l) for l in T}
    title='Uniformes y soluciones textiles en Monterrey | PTN' if lang=='es' else 'Uniforms & Textile Solutions in Monterrey, Mexico | PTN'
    desc='PTN: uniformes empresariales, bordado, serigrafía, DTF, sublimación y materia prima textil. Atención desde Monterrey y envíos a todo México.' if lang=='es' else 'PTN supplies corporate uniforms, embroidery, screen printing, DTF, sublimation and wholesale textiles from Monterrey to businesses across Mexico.'
    main='Uniformes y soluciones textiles para la industria.' if lang=='es' else 'Uniforms and textile solutions for industry.'
    intro='Vestimos equipos de trabajo en México con uniformes industriales, ejecutivos y casuales. Integramos personalización, materia prima textil y suministro para tu operación.' if lang=='es' else 'We outfit teams across Mexico with industrial, executive and casual uniforms, customization, wholesale textiles and supply programs for your operation.'
    stats=[('6','ÁREAS DE SERVICIO'),('4','TÉCNICAS DE PERSONALIZACIÓN'),('B2B','ATENCIÓN A EMPRESAS'),('MX','COBERTURA NACIONAL')] if lang=='es' else [('6','SERVICE AREAS'),('4','CUSTOMIZATION TECHNIQUES'),('B2B','BUSINESS PROJECTS'),('MX','NATIONWIDE COVERAGE')]
    pillars=[BY_SLUG[x] for x in ['uniformes-empresariales','personalizacion-textil','materia-prima-textil','diseno-y-confeccion','programas-de-uniformes','distribucion-multisucursal']]
    body=f'''<section class="dark"><div class="hero"><div class="wrap hero-grid"><div><span class="eyebrow">{t['location']} — {'Soluciones textiles B2B' if lang=='es' else 'B2B textile solutions'}</span><h1>{main}</h1><p class="intro">{intro}</p>{actions(lang,light=True)}<p style="font-size:12px;margin-top:22px;color:#c8c6e3">{'De la prenda a tu marca. Del primer pedido a la reposición.' if lang=='es' else 'From garment to brand. From your first order to replenishment.'}</p></div><figure class="hero-figure">{img('soluciones-textiles','Telas y equipos de bordado' if lang=='es' else 'Fabrics and embroidery equipment',True,'hero-photo')}</figure></div></div><div class="wrap stats">{''.join('<div class="stat"><strong>'+v+'</strong><span>'+l+'</span></div>' for v,l in stats)}</div></section><section class="section"><div class="wrap"><div class="section-head"><div><span class="eyebrow">{t['services']}</span><h2>{'Todo el ciclo textil de tu empresa, en un solo proveedor.' if lang=='es' else 'Your company’s textile cycle, from a single supplier.'}</h2></div><a class="text-link" href="{route('services',lang)}">{t['all']} ↗</a></div>{cards(pillars,lang)}</div></section><section class="section white"><div class="wrap two-col"><div><span class="eyebrow">{t['customization']}</span><h2>{'Tu marca, en la técnica adecuada.' if lang=='es' else 'Your brand, with the right technique.'}</h2><p class="lead">{'El material, el arte y el volumen ayudan a elegir el acabado. Compara las cuatro opciones antes de cotizar.' if lang=='es' else 'Material, artwork and volume help determine the finish. Compare the four options before requesting a quote.'}</p>{img('bordado','Logotipo bordado sobre una prenda negra' if lang=='es' else 'Embroidered logo on a black garment')}</div><div class="tech-list">'''
    techniques=[BY_SLUG[x] for x in ['bordado','serigrafia','impresion-dtf','sublimacion']]
    for i,s in enumerate(techniques):body+=f'<a class="tech-item" href="{service_route(s,lang)}"><span>{i+1:02d}</span><div><h3>{e(s[lang]["name"])}</h3><p>{e(s[lang]["description"])}</p></div><span aria-hidden="true">↗</span></a>'
    body+=f'''</div></div></section><section class="section"><div class="wrap"><div class="section-head"><div><span class="eyebrow">{t['clients']}</span><h2>{'Empresas que confían en PTN' if lang=='es' else 'Companies that trust PTN'}</h2></div><a class="text-link" href="{route('clients',lang)}">{t['clients']} ↗</a></div>{logo_grid(SITE['clients'])}</div></section><section class="section white"><div class="wrap"><div class="section-head"><div><span class="eyebrow">{t['brands']}</span><h2>{'Marcas que distribuimos' if lang=='es' else 'Brands we distribute'}</h2></div><a class="text-link" href="{route('brands',lang)}">{t['brands']} ↗</a></div>{logo_grid(SITE['brands'][:8],True)}</div></section>'''+band(lang)
    questions=[('¿Qué servicios ofrece PTN?','Uniformes industriales, ejecutivos y casuales; bordado, serigrafía, DTF y sublimación; materia prima textil; diseño y confección; programas de uniformes; y distribución multisucursal.'),('¿Dónde está PTN y a dónde envía?','PTN está en Monterrey, Nuevo León, y publica cobertura de envío en México. Comparte tu código postal para confirmar condiciones de entrega.'),('¿Cómo puedo solicitar una cotización?','Prepara prendas o materiales, cantidades, tallas, diseño y destino. Contacta por WhatsApp, al +52 81 2028 8728 o en ventas@ptntextiles.com.')] if lang=='es' else [('Which services does PTN offer?','Industrial, executive and casual uniforms; embroidery, screen printing, DTF and sublimation; textile materials; custom design; uniform programs; and multi-location distribution.'),('Where is PTN based and where does it ship?','PTN is based in Monterrey, Nuevo León, with published shipping coverage in Mexico. Provide your postal code to confirm delivery terms.'),('How can I request a quote?','Prepare garment or material specifications, quantities, sizes, artwork and destination. Contact PTN through WhatsApp, +52 81 2028 8728 or ventas@ptntextiles.com.')]
    body+=faq(questions,lang)
    write(path,layout(path,lang,title,desc,body,'home',alts),alternates=alts)

def directory(lang):
    t=T[lang];path=route('services',lang);alts={l:route('services',l) for l in T}
    title='Servicios textiles para empresas en Monterrey | PTN' if lang=='es' else 'Textile Services for Businesses in Mexico | PTN'
    desc='Explora los servicios de PTN: uniformes, personalización, telas al mayoreo, confección, programas empresariales y distribución a sucursales.' if lang=='es' else 'Explore PTN services: corporate uniforms, customization, wholesale fabrics, custom garments, recurring supply and multi-location distribution in Mexico.'
    crumbs=[(t['home'],route('home',lang)),(t['services'],path)]
    body=breadcrumbs(crumbs)+f'<section class="page-intro"><div class="wrap"><span class="eyebrow">PTN / {t["services"]}</span><h1>{"Servicios y capacidades textiles para tu empresa" if lang=="es" else "Textile services and capabilities for your business"}</h1><p class="lead">{e(desc)}</p></div></section><section class="section service-groups"><div class="wrap">'
    for group,label in [('uniformes','uniforms'),('personalizacion','customization'),('suministro','supply')]:body+=f'<h2>{t[label]}</h2>'+cards([s for s in SERVICES if s['group']==group],lang)
    body+='</div></section>'+band(lang)
    write(path,layout(path,lang,title,desc,body,'services',alts,crumbs=crumbs),alternates=alts)

def contact(lang):
    t=T[lang];path=route('contact',lang);alts={l:route('contact',l) for l in T}
    title='Cotiza uniformes y servicios textiles | Contacto PTN' if lang=='es' else 'Request Uniforms & Textile Services | Contact PTN'
    desc='Contacta a PTN en Monterrey para cotizar uniformes, personalización y textiles. WhatsApp y teléfono +52 81 2028 8728; ventas@ptntextiles.com.' if lang=='es' else 'Contact PTN in Monterrey for uniforms, customization and textiles. Phone and WhatsApp +52 81 2028 8728; ventas@ptntextiles.com.'
    crumbs=[(t['home'],route('home',lang)),(t['contact'],path)]
    fields=[]
    for name,label,kind,required in [('nombre','name','text',True),('empresa','company','text',True),('email','email','email',True),('telefono','phone','tel',False)]:
        autocomplete={'nombre':'name','empresa':'organization','email':'email','telefono':'tel'}[name]
        fields.append(f'<div class="field"><label for="{name}">{t[label]}</label><input id="{name}" name="{name}" type="{kind}" autocomplete="{autocomplete}" maxlength="160" {"required" if required else ""}></div>')
    options='<option value="">'+t['other']+'</option>'+''.join(f'<option value="{s["slug"]}">{e(s[lang]["name"])}</option>' for s in SERVICES)
    body=breadcrumbs(crumbs)+f'''<section class="page-intro"><div class="wrap"><span class="eyebrow">PTN / {t['contact']}</span><h1>{t['formTitle']}</h1><p class="lead">{t['formIntro']}</p></div></section><section class="section" style="padding-top:15px"><div class="wrap contact-grid"><div><form class="quote-form" id="quote-form" action="https://wa.me/528120288728" method="get"><div class="form-grid">{''.join(fields)}<div class="field wide"><label for="servicio">{t['serviceLabel']}</label><select id="servicio" name="servicio">{options}</select></div><div class="field"><label for="cantidad">{t['quantity']}</label><input id="cantidad" name="cantidad" type="text" maxlength="100"></div><div class="field"><label for="ciudad">{t['city']}</label><input id="ciudad" name="ciudad" autocomplete="address-level2" maxlength="150" required></div><div class="field wide"><label for="mensaje">{t['message']}</label><textarea id="mensaje" name="mensaje" maxlength="3000"></textarea></div></div><p class="form-note">{t['formNote']}</p><button class="button" type="submit" disabled>{t['formButton']} ↗</button><p class="form-status" id="form-status" aria-live="polite"></p><noscript><p>{'Para preparar el formulario se necesita JavaScript. Puedes contactar directamente por los enlaces de WhatsApp, teléfono o correo de esta página.' if lang=='es' else 'JavaScript is needed to prepare this form. Use the direct WhatsApp, phone or email links on this page.'}</p></noscript></form></div><aside><div class="contact-info"><h2>WHATSAPP / {'TELÉFONO' if lang=='es' else 'PHONE'}</h2><p><a data-track="phone_click" href="tel:{SITE['phoneRaw']}">{SITE['phone']}</a></p><a class="text-link" data-track="whatsapp_click" href="https://wa.me/{SITE['whatsapp']}" target="_blank" rel="noopener noreferrer">{t['whatsapp']} ↗</a></div><div class="contact-info"><h2>EMAIL</h2><p><a data-track="email_click" href="mailto:{SITE['email']}">{SITE['email']}</a></p></div><div class="contact-info"><h2>{t['address']}</h2><p>{SITE['street']}<br>{SITE['postalCode']} Monterrey, Nuevo León, México</p><a class="text-link" href="https://maps.google.com/?q=Santiago+Tapia+Pte+1710+Centro+64000+Monterrey+NL" target="_blank" rel="noopener noreferrer">{'Ver ubicación' if lang=='es' else 'View location'} ↗</a></div><div class="contact-info"><h2>{'HORARIO' if lang=='es' else 'HOURS'}</h2><p>{t['hours']}<br>{'Zona horaria de Monterrey' if lang=='es' else 'Monterrey local time'}</p></div></aside></div></section>'''
    write(path,layout(path,lang,title,desc,body,'contact',alts,crumbs=crumbs),alternates=alts)

def supporting(key,lang):
    t=T[lang];path=route(key,lang);alts={l:route(key,l) for l in T};crumbs=[(t['home'],route('home',lang)),(t[key],path)]
    if key=='about':
        title='Parches y Textiles del Norte | Nosotros — PTN' if lang=='es' else 'About Parches y Textiles del Norte | PTN'
        desc='Conoce PTN, empresa de Monterrey especializada en uniformes, personalización y suministro textil para negocios con cobertura nacional.' if lang=='es' else 'Meet PTN, a Monterrey company offering uniforms, customization and textile supply for businesses across Mexico.'
        heading='Parches y Textiles del Norte' if lang=='es' else 'Parches y Textiles del Norte'
        text='PTN reúne venta de uniformes industriales, ejecutivos y casuales, personalización y suministro de materia prima textil para empresas. Desde Monterrey, Nuevo León, atendemos proyectos que van de una dotación de prendas a programas de suministro recurrente y distribución a varias sedes.' if lang=='es' else 'PTN combines industrial, executive and casual uniforms, customization and textile material supply for businesses. From Monterrey, Nuevo León, projects range from a single garment allocation to recurring supply and multi-location distribution.'
        body=f'<section class="section"><div class="wrap two-col center"><div><span class="eyebrow">{t["about"]} / Monterrey</span><h1>{heading}</h1><p class="lead">{text}</p><p>{"La propuesta se define a partir del uso de la prenda, el diseño, las cantidades y el destino. Revisamos contigo el alcance para que puedas comparar opciones y acordar el suministro." if lang=="es" else "The proposal starts with garment use, artwork, quantities and destination. We review the scope so you can compare options and agree supply terms."}</p>{actions(lang)}</div>{img("soluciones-textiles",t["caption"])}</div></section><section class="section white"><div class="wrap"><h2>{"De la materia prima a la prenda con tu marca" if lang=="es" else "From materials to branded garments"}</h2>{cards([BY_SLUG[s] for s in ["uniformes-empresariales","personalizacion-textil","materia-prima-textil"]],lang)}</div></section>'
    else:
        is_brand=key=='brands'
        heading=('Marcas que distribuimos' if is_brand else 'Empresas que confían en PTN') if lang=='es' else ('Brands we distribute' if is_brand else 'Companies that trust PTN')
        title=heading+' | PTN'
        desc=('Marcas de prendas y textiles que PTN presenta en su oferta. Consulta modelos, tallas, colores y disponibilidad para tu proyecto.' if is_brand else 'Conoce las empresas que PTN presenta en su portafolio de uniformes y suministro textil. Cuéntanos los requisitos de tu organización.') if lang=='es' else ('Garment and textile brands listed by PTN. Confirm models, sizes, colors and availability for your project.' if is_brand else 'Explore the companies in PTN’s published uniform and textile supply portfolio. Tell us what your organization needs.')
        note=('Las marcas y modelos están sujetos a disponibilidad. Los enlaces externos abren los sitios de las marcas; la cotización y el suministro se revisan directamente con PTN.' if is_brand else 'Cada empresa tiene necesidades distintas. Para preparar tu propuesta, comparte prendas, cantidades, identidad de marca y destinos. Las referencias de este portafolio no describen un caso de estudio ni implican que todos los servicios se hayan prestado a cada empresa.') if lang=='es' else ('Brands and models are subject to availability. External links open brand websites; discuss quotations and supply with PTN.' if is_brand else 'Each business has different requirements. Share garments, quantities, branding and destinations. Portfolio references are not detailed case studies and do not imply every service was provided to each company.')
        body=f'<section class="page-intro"><div class="wrap"><span class="eyebrow">PTN / {t[key]}</span><h1>{heading}</h1><p class="lead">{desc}</p></div></section><section class="section" style="padding-top:20px"><div class="wrap">{logo_grid(SITE["brands" if is_brand else "clients"],is_brand)}<p style="margin-top:30px;max-width:850px;color:var(--muted)">{note}</p>{actions(lang)}</div></section>'
    body=breadcrumbs(crumbs)+body+band(lang)
    write(path,layout(path,lang,title,desc,body,key,alts,crumbs=crumbs),alternates=alts)

def build():
    if len(SERVICES)!=13 or len(BY_SLUG)!=13: raise ValueError('Expected 13 distinct services')
    for s in SERVICES:
        assert all(r in BY_SLUG for r in s['related'])
        assert (ROOT/media(s['image']).lstrip('/')).exists()
    for lang in T:
        home(lang); directory(lang); contact(lang)
        for key in ['about','clients','brands']: supporting(key,lang)
        for s in SERVICES: service_page(s,lang)
    body='<section class="not-found"><div class="wrap"><span class="eyebrow">404 / PTN</span><h1>Página no encontrada</h1><p>La dirección no existe. Puedes explorar los servicios de PTN o volver al inicio.</p><div class="actions"><a class="button" href="/">Volver al inicio</a><a class="button outline" href="/servicios/">Ver servicios</a></div></div></section>'
    (ROOT/'404.html').write_text(layout('/404.html','es','Página no encontrada | PTN','La dirección solicitada no existe.',body,'home',noindex=True))
    ET.register_namespace('','http://www.sitemaps.org/schemas/sitemap/0.9'); ET.register_namespace('xhtml','http://www.w3.org/1999/xhtml')
    ns='http://www.sitemaps.org/schemas/sitemap/0.9'; x='http://www.w3.org/1999/xhtml';tree=ET.Element('{'+ns+'}urlset')
    for item in ROUTES:
        n=ET.SubElement(tree,'{'+ns+'}url');ET.SubElement(n,'{'+ns+'}loc').text=URL+item['path']
        for lang,path in item['alternates'].items():ET.SubElement(n,'{'+x+'}link',{'rel':'alternate','hreflang':'es-MX' if lang=='es' else 'en','href':URL+path})
        ET.SubElement(n,'{'+x+'}link',{'rel':'alternate','hreflang':'x-default','href':URL+item['alternates']['es']})
    ET.indent(tree);(ROOT/'sitemap.xml').write_bytes(ET.tostring(tree,encoding='utf-8',xml_declaration=True))
    (ROOT/'robots.txt').write_text('User-agent: *\nAllow: /\nDisallow: /content/\nDisallow: /scripts/\n\nUser-agent: OAI-SearchBot\nAllow: /\nDisallow: /content/\nDisallow: /scripts/\n\nSitemap: '+URL+'/sitemap.xml\n')
    (ROOT/'content/routes.json').write_text(json.dumps(ROUTES,ensure_ascii=False,indent=2)+'\n')
    with (ROOT/'docs/mapa-servicios-seo-geo.csv').open('w',newline='') as f:
        w=csv.writer(f,lineterminator="\n");w.writerow(['URL ES','URL EN','Servicio','Familia','Pregunta principal','Búsqueda principal','Búsquedas relacionadas','Prioridad propuesta','Intención','Volumen de búsqueda'])
        for s in SERVICES:w.writerow([URL+service_route(s,'es'),URL+service_route(s,'en'),s['es']['name'],s['group'],s['es']['faqs'][0][0],SEO_PLAN[s['slug']]['keywords'][0],' | '.join(SEO_PLAN[s['slug']]['keywords'][1:]),SEO_PLAN[s['slug']]['priority'],'Comercial B2B / cotización','No medido'])
    print(f'Generated {len(ROUTES)} indexable pages, 26 service pages, sitemap.xml, robots.txt and 404.html.')

if __name__=='__main__': build()
